import java.io.*;
import java.nio.file.Path;

public class ByteStreamExample {
    public void readImageFile(Path imagePath) throws IOException {
        // Wrap FileInputStream with BufferedInputStream for performance
        try (var buffered = new BufferedInputStream(
                 new FileInputStream(imagePath.toFile()))) {

            int byteValue;
            int bytesRead = 0;

            // Read until we hit end-of-stream (-1)
            while ((byteValue = buffered.read()) != -1) {
                // Process each byte (0-255)
                bytesRead++;
            }

            System.out.println("Read " + bytesRead + " bytes from image");
        } // Auto-closes both streams
    }
}

import java.io.*;
import java.nio.file.*;

public class FileCopyService {

    public void copyFileManual(Path source, Path destination) throws IOException {
        // Try-with-resources ensures streams close automatically
        try (var input = new BufferedInputStream(
                 new FileInputStream(source.toFile()));
             var output = new BufferedOutputStream(
                 new FileOutputStream(destination.toFile()))) {

            var buffer = new byte[8192]; // 8KB buffer
            int bytesRead;

            // Read chunks until end-of-file (-1)
            while ((bytesRead = input.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead); // Write exact bytes read
            }
        }
    }

    public void copyFileModern(Path source, Path destination) throws IOException {
        Files.copy(source, destination, StandardCopyOption.REPLACE_EXISTING);
    }
}

import java.io.*;

record CustomerOrder(Long id, String item, double price) implements Serializable {}

public class SerializationTest {

    public byte[] serializeOrder(CustomerOrder order) throws IOException {
        var byteOutput = new ByteArrayOutputStream();

        // ObjectOutputStream writes to in-memory stream
        try (var objectOutput = new ObjectOutputStream(byteOutput)) {
            objectOutput.writeObject(order);
        }

        return byteOutput.toByteArray(); // Get all written bytes
    }

    public void testRoundTrip() throws Exception {
        var original = new CustomerOrder(123L, "Laptop", 899.99);

        // Serialize to byte array in memory
        var bytes = serializeOrder(original);

        // Deserialize from byte array
        var byteInput = new ByteArrayInputStream(bytes);
        try (var objectInput = new ObjectInputStream(byteInput)) {
            var deserialized = (CustomerOrder) objectInput.readObject();
            assert original.equals(deserialized);
        }
    }
}

import java.io.*;
import java.nio.file.*;

public class FileReader {

    private static final long SIZE_THRESHOLD = 50 * 1024 * 1024; // 50MB

    public byte[] readFileSmall(Path path) throws IOException {
        // Simple one-liner for small files
        return Files.readAllBytes(path);
    }

    public byte[] readFileLarge(Path path) throws IOException {
        var output = new ByteArrayOutputStream();

        try (var input = new BufferedInputStream(
                 new FileInputStream(path.toFile()))) {

            var buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = input.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }
        }

        return output.toByteArray();
    }

    public byte[] readFileSmart(Path path) throws IOException {
        long size = Files.size(path);
        return size < SIZE_THRESHOLD 
            ? readFileSmall(path) 
            : readFileLarge(path);
    }
}
